// ─── Calcula rango de fechas y referencias del mes corriente ───
// Output:
//   primerDia        → lunes ISO de la semana que contiene el día 1 del mes corriente (YYYY-MM-DD)
//   ultimoDia        → último sábado ≤ hoy (YYYY-MM-DD)
//   diaUnoMes        → día 1 del mes corriente (YYYY-MM-DD)
//   mesCorriente     → YYYY-MM del mes corriente
//   mesAnioCorriente → año del mes corriente
//   ultimoSabado     → alias legacy de ultimoDia (por compatibilidad con templates)

const tz = 'America/Montevideo';

const hoy = DateTime.now().setZone(tz).startOf('day');

// Luxon weekday: 1=Lun ... 6=Sáb, 7=Dom
const diasAlSabado = (hoy.weekday + 1) % 7; // Sáb→0, Dom→1, Lun→2, ...
const ultimoDia = hoy.minus({ days: diasAlSabado });

const mesActual = hoy.startOf('month');
const primerDia = mesActual.startOf('week'); // Luxon: startOf('week') = lunes ISO

return [
  {
    json: {
      primerDia:        primerDia.toISODate(),
      ultimoDia:        ultimoDia.toISODate(),
      diaUnoMes:        mesActual.toISODate(),
      mesCorriente:     mesActual.toFormat('yyyy-MM'),
      mesAnioCorriente: mesActual.year,
      ultimoSabado:     ultimoDia.toISODate(),
    },
  },
];

// ─── Clasifica y filtra cada pago ───
// - Filtra fecha < primerDia (fuera de rango).
// - Filtra código de prestación no válido.
// - Normaliza Categoria (11 categorías oficiales + OTRO).
// - Asigna Clase (AJUSTE / COMBO / RETIRO / OTRO).
// - Calcula mesKey (YYYY-MM), semanaAnio (S{N} — convención Sonrisas), semanaMes (Semana {N} — lu-do con S1 desde día 1 y última hasta fin mes).
// - Resuelve docId de sucursal.
// - Marca esDelMesActual (fecha >= día 1 del mes corriente).

const tz = 'America/Montevideo';

// ═══ CONFIG ═══════════════════════════════════════════════════════
const CODIGOS_VALIDOS = new Set([
  "00001",
  "A0000","A0001","A0002","A0003","A0004","A0005","A0007",
  "C0000","C0001","C0002","C0003","C0004","C0005","C0006","C0007","C0008","C0009","C0010","C0011","C0012","C0013","C0014","C0050","C0051","C0052","C0053","C0054","C0055","C0056","C0057",
  "E0001","E0002","E0003","E0004","E0005","E0006","E0007","E0008","E0050","E0051","E0052",
  "HB000","HB001","HB002","HB003","HB004","HB005","HB006","HB007",
  "OA001","OA002","OA003","OA004","OA005","OA006","OA007","OA008","OA009","OA010","OA011","OA012","OA013","OA014","OA015","OA016","OA017","OA018","OA019","OA020","OA021","OA022","OA023","OA024","OA025","OA026","OA027","OA028","OA029","OA030","OA031","OA032","OA033","OA034","OA035","OA036","OA037","OA038","OA039","OA040","OA041","OA042","OA043","OA044","OA045","OA046","OA047","OA100","OA101","OA102","OA103","OA104","OA105","OA106","OA107","OA108","OA109","OA110","OA111","OA200","OA201","OA202","OA203","OA204","OA205","OA206","OA207","OA208","OA300","OA301","OA302","OA600","OA601","OA602","OA603","OA604","OA605","OA606","OA607","OA608","OA609","OA700","OA701","OA702","OA703","OA704","OA800","OA801",
  "OG001","OG002","OG003","OG004","OG005","OG006","OG007","OG020","OG021","OG022","OG023","OG024","OG025","OG026","OG027","OG028","OG040","OG041","OG042","OG043","OG044","OG045","OG046","OG047","OG048","OG049","OG050","OG051","OG060","OG061","OG062","OG063","OG064","OG065","OG066","OG067","OG068","OG070","OG071","OG072","OG073","OG074","OG075","OG080","OG081","OG082",
  "OP000","OP001","OP100","OP101","OP102","OP103","OP104","OP105","OP106","OP107","OP108","OP109","OP110","OP111","OP112","OP113","OP114","OP115","OP116","OP117","OP118","OP119","OP200","OP201","OP202","OP203","OP204","OP205",
  "OR001","OR002","OR003","OR004","OR005","OR006","OR007","OR008","OR009","OR010","OR011","OR012","OR013","OR014","OR016","OR017","OR018","OR019","OR020","OR021","OR100","OR101","OR102","OR103","OR104","OR105","OR106","OR107","OR108","OR109","OR110","OR111","OR112","OR113","OR114","OR115","OR116","OR117","OR118","OR119","OR120","OR121","OR122","OR123","OR124","OR125","OR200","OR201","OR202",
  "P0000","P0001","P0002","P0003","P0004","P0005","P0006","P0007","P0008","P0009","P0010","P0011","P1000","P1001","P1002","P1003","P1004","P1005","P2000","P2001","P2002","P2003","P2004","P2005","P2006","P2007","P2008","P2009","P3000","P3001","P3002","P3003","P3004","P3005","P3006","P3007","P3008",
  "RD000","RD001","RD002","RD003","RD004","RD005","RD006","RD007"
]);

// Matching de Categoria (orden importante: primera regex que matchee)
const CATEGORIAS = [
  { match: /ENDODONCIA/,                 out: 'ENDODONCIA' },
  { match: /CIRUGIA/,                    out: 'CIRUGIA' },
  { match: /^ODONTOLOGIA GENERAL$/,      out: 'GENERAL' },
  { match: /PROTESIS/,                   out: 'PROTESIS' },
  { match: /ORTOPEDIA/,                  out: 'ORTOPEDIA' },
  { match: /ORTODONCIA/,                 out: 'ORTODONCIA' },
  { match: /PERIODONCIA/,                out: 'PERIODONCIA' },
  { match: /^PRODUCTOS HIGIENE BUCAL$/,  out: 'PRODUCTOS HIGIENE BUCAL' },
  { match: /RADIOLOGIA/,                 out: 'RADIOLOGIA' },
  { match: /ALINEADORES/,                out: 'ALINEADORES' },
];

// Matching de Clase por código de prestación
const CLASES = [
  { clase: 'AJUSTE', match: /^OA/ },
  { clase: 'COMBO',  match: /^OR(1\d\d|2\d\d)$/ },  // OR100–OR299
  { clase: 'RETIRO', match: /^OR00[1-7]$/ },         // OR001–OR007
];

// Mapeo sucursal número → docId
const DOC_ID_SUCURSAL = {
  '1': '1GUVq5XdG7ltgXmOlyVf7ucgMsceE7k84OyLt-2E96dc',
  '2': '1xowQTStDe4xjDabW0sgOpuuuix3Kv-vUpQTB8Lsmoqk',
  '3': '1ec8XrB9qcKkRUTGjoewXPx0yKuS3fe4bG6ypF3R408A',
  '4': '1CaUQQtLcgxAkgIdT6Snmpf8KhnHNTDuPSsHbgqmCWWI',
};

// ═══ HELPERS ══════════════════════════════════════════════════════
const { primerDia, diaUnoMes } = $('lapso').first().json;
const fechaLimite = DateTime.fromISO(primerDia, { zone: tz });
const diaUno      = DateTime.fromISO(diaUnoMes, { zone: tz });

const normaliza = (s) =>
  String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().trim();

const detectarCategoria = (v) => {
  const n = normaliza(v);
  for (const c of CATEGORIAS) if (c.match.test(n)) return c.out;
  return 'OTRO';
};

const detectarClase = (codigo) => {
  for (const c of CLASES) if (c.match.test(codigo)) return c.clase;
  return 'OTRO';
};

// Semana del año — convención Sonrisas: S1 = del 1/1 hasta primer domingo; S2+ = lunes-domingo.
const semanaAnio = (dt) => {
  const jan1 = dt.startOf('year');
  const daysToFirstSunday = (7 - jan1.weekday) % 7; // Dom=7 → 0
  const firstSunday = jan1.plus({ days: daysToFirstSunday });
  if (dt <= firstSunday) return 'S1';
  const firstMonday = firstSunday.plus({ days: 1 });
  const diffDays = Math.floor(dt.diff(firstMonday, 'days').days);
  return 'S' + (2 + Math.floor(diffDays / 7));
};

// Semana del mes — S1 desde día 1 hasta primer domingo; S2+ = lu-do; última termina fin de mes.
const semanaMes = (dt, ancla) => {
  const monthStart = ancla;
  const daysToFirstSunday = (7 - monthStart.weekday) % 7;
  const firstSunday = monthStart.plus({ days: daysToFirstSunday });
  if (dt <= firstSunday) return 'Semana 1';
  const firstMonday = firstSunday.plus({ days: 1 });
  const diffDays = Math.floor(dt.diff(firstMonday, 'days').days);
  return 'Semana ' + (2 + Math.floor(diffDays / 7));
};

// ═══ PROCESO ══════════════════════════════════════════════════════
const out = [];

for (const item of items) {
  const r = item.json || {};

  // Fecha
  const fechaStr = r['Fecha de recepción del pago'];
  if (!fechaStr) continue;
  const dt = DateTime.fromFormat(String(fechaStr), 'yyyy-MM-dd', { zone: tz }).startOf('day');
  if (!dt.isValid) continue;
  if (dt < fechaLimite) continue;

  // Código
  const codigo = String(r['Código Prestación'] || '').trim().toUpperCase();
  if (!CODIGOS_VALIDOS.has(codigo)) continue;

  // Sucursal
  const sucursal = r['Nombre Sucursal'] || '';
  const sucursalMatch = sucursal.match(/\d+/);
  if (!sucursalMatch) continue;
  const sucursalNum = sucursalMatch[0];
  const docId = DOC_ID_SUCURSAL[sucursalNum];
  if (!docId) continue;

  out.push({
    json: {
      fecha:            dt.toISODate(),
      Sucursal:         sucursal,
      SucursalNumero:   sucursalNum,
      docId,
      Mes:              r['Mes de recepción del pago'],
      mesKey:           dt.toFormat('yyyy-MM'),
      Semana:           semanaAnio(dt),
      Semana_mes:       semanaMes(dt, diaUno),
      Categoria:        detectarCategoria(r['Nombre categoría']),
      Clase:            detectarClase(codigo),
      pagadoPrestacion: Number(r['Pagado Prestación'] || 0),
      abonoLibre:       Number(r['Abono Libre'] || 0),
      esDelMesActual:   dt >= diaUno,
    },
  });
}

return out;

// Duplicado del nodo 'lapso' para alimentar el sub-flujo de recordatorio a Cecilia.
// Se mantiene idéntico para que ambos flujos compartan la misma lógica.

const tz = 'America/Montevideo';

const hoy = DateTime.now().setZone(tz).startOf('day');
const diasAlSabado = (hoy.weekday + 1) % 7;
const ultimoDia = hoy.minus({ days: diasAlSabado });
const mesActual = hoy.startOf('month');
const primerDia = mesActual.startOf('week');

return [
  {
    json: {
      primerDia:        primerDia.toISODate(),
      ultimoDia:        ultimoDia.toISODate(),
      diaUnoMes:        mesActual.toISODate(),
      mesCorriente:     mesActual.toFormat('yyyy-MM'),
      mesAnioCorriente: mesActual.year,
      ultimoSabado:     ultimoDia.toISODate(),
    },
  },
];

