const normalizeKey = (s) =>
  String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '')
                 .replace(/[^\w]+/g, '_').replace(/^_+|_+$/g, '').replace(/_+/g, '_')
                 .toUpperCase();

function acumular(map, key, r) {
  if (!map.has(key)) {
    map.set(key, { _groupKey: r._groupKey, Sucursal: r.Sucursal, docId: r.docId, sum_Abono_Libre: 0 });
  }
  const agg = map.get(key);
  agg.sum_Abono_Libre += r.abonoLibre;
  const catCol = 'sum_' + normalizeKey(r.Categoria);
  agg[catCol] = (agg[catCol] || 0) + r.pagadoPrestacion;
  agg['pagado' + r.Clase] = (agg['pagado' + r.Clase] || 0) + r.pagadoPrestacion;
  agg['cantidad' + r.Clase] = (agg['cantidad' + r.Clase] || 0) + 1;
}

const toItems = (map, fieldName) =>
  Array.from(map.values()).map(v => {
    const { _groupKey, ...rest } = v;
    return { json: { [fieldName]: _groupKey, ...rest } };
  });

// Solo filas del mes corriente (esDelMesActual=true)
